// AWI: diagnosa harga TiTAN (sementara, hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tdiag4', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			$out = array();
			$p = get_post(10706);
			$out['type'] = $p->post_type;
			$out['tpl'] = get_page_template_slug(10706);
			$m = get_post_meta(10706);
			foreach ($m as $k => $v) { $s = maybe_serialize($v[0]); if (stripos($k, 'harga') !== false || stripos($k, 'price') !== false || stripos($s, 'Rp') !== false || stripos($k, 'otr') !== false) $out['meta'][$k] = substr($s, 0, 300); }
			$out['metakeys'] = array_values(array_filter(array_keys($m), function ($k) { return $k[0] !== '_'; }));
			$c = $p->post_content;
			$out['len'] = strlen($c);
			$out['hd'] = array();
			if (preg_match_all('#<h2[^>]*>(.*?)</h2>#s', $c, $mm, PREG_OFFSET_CAPTURE)) foreach ($mm[1] as $x) $out['hd'][] = $x[1] . ' ' . wp_strip_all_tags($x[0]);
			$out['harga'] = array();
			$o = 0; while (($i = stripos($c, 'harga', $o)) !== false && count($out['harga']) < 12) { $out['harga'][] = $i . ' ' . wp_strip_all_tags(substr($c, max(0, $i - 80), 220)); $o = $i + 5; }
			$o = 0; $out['rp'] = array(); while (($i = strpos($c, 'Rp', $o)) !== false && count($out['rp']) < 8) { $out['rp'][] = $i . ' ' . wp_strip_all_tags(substr($c, max(0, $i - 100), 200)); $o = $i + 2; }
			$o2 = get_post(10709); $out['cmp_type'] = $o2 ? $o2->post_type : null;
			$q = get_posts(array('post_type' => $p->post_type, 'numberposts' => 3, 'exclude' => array(10706)));
			foreach ($q as $x) { $mx = get_post_meta($x->ID); $kk = array(); foreach ($mx as $k => $v) if ($k[0] !== '_') $kk[$k] = substr(maybe_serialize($v[0]), 0, 120); $out['other'][$x->ID] = array($x->post_name, $kk); }
			return $out;
		},
	));
});
